INSERT INTO "product_landings" ("id", "slug", "status", "category", "brand_name", "footer_text", "name", "eyebrow", "description", "long_description", "price", "old_price", "hero_image", "gallery", "features", "steps", "specs", "faq", "final_cta_title") VALUES
	(gen_random_uuid()::text, 'didelis-plepus-zaislas', 'active', 'namams', 'Milishop', 'Apgalvoti daiktai kasdienai.', 'Didelis pūkus žaislas 180 cm – baltas', 'Milishop pasirinkimas · Namams', 'Minkštas ir jaukus žaislas namams.', 'Minkštas ir jaukus žaislas namams.', '131,82 €', '€131,82', 'https://images.unsplash.com/photo-1517849845537-4d257902454a?auto=format&fit=crop&w=900&q=80', '["https://images.unsplash.com/photo-1517849845537-4d257902454a?auto=format&fit=crop&w=900&q=80"]', '[]', '[]', '[]', '[]', 'Didelis pūkus žaislas 180 cm – baltas'),
	(gen_random_uuid()::text, 'obd2', 'active', 'automobiliui', 'Milishop', 'Apgalvoti daiktai kasdienai.', 'OBD2 automobilio diagnostikos įrenginys', 'Milishop #01 · Automobiliui', 'Daugiau aiškumo prieš kelionę, servisą ar tiesiog kasdienį važiavimą.', 'Kompaktiškas OBD2 įrenginys padeda suprasti, kas vyksta tavo automobilyje. Prijunk, atsidaryk programėlę ir matyk svarbiausią informaciją vienoje vietoje — be sudėtingų meniu ar spėlionių. Tai patogus pirmas žingsnis, kai nori geriau pažinti savo automobilį.', '39,90 €', '49,90 €', 'https://cdn.builder.io/api/v1/image/assets%2Fd04450a0da6f48df807f14687fdbf7fe%2F1cf73157227448c7a9abcdea548b4cb3?format=webp&width=800&height=1200', '["https://cdn.builder.io/api/v1/image/assets%2Fd04450a0da6f48df807f14687fdbf7fe%2F1cf73157227448c7a9abcdea548b4cb3?format=webp&width=800&height=1200","https://cdn.builder.io/api/v1/image/assets%2Fd04450a0da6f48df807f14687fdbf7fe%2F539cd33740b54e819abe0b450e6b2e03?format=webp&width=800&height=1200","https://cdn.builder.io/api/v1/image/assets%2Fd04450a0da6f48df807f14687fdbf7fe%2F88e523bfe09b4316949e448a2f14c72b?format=webp&width=800&height=1200","https://cdn.builder.io/api/v1/image/assets%2Fd04450a0da6f48df807f14687fdbf7fe%2F74a6c2b42d5e4c23b5bbe39577b18ed1?format=webp&width=800&height=1200","https://cdn.builder.io/api/v1/image/assets%2Fd04450a0da6f48df807f14687fdbf7fe%2F23e189594a364d70b3cf875d33aa04f9?format=webp&width=800&height=1200","https://cdn.builder.io/api/v1/image/assets%2Fd04450a0da6f48df807f14687fdbf7fe%2F4f167c94667d4251a5b5a12948ff41f6?format=webp&width=800&height=1200"]', '["Aiškesnė automobilio būklė","Paprastas prijungimas","Kompaktiškas dydis"]', '["Prijunk įrenginį prie OBD2 jungties","Atidaryk suderinamą programėlę","Peržiūrėk informaciją ir klaidų kodus"]', '[{"label":"Jungtis","value":"OBD2 / 16 pin"},{"label":"Suderinamumas","value":"12 V automobiliai"},{"label":"Naudojimas","value":"Asmeniniam naudojimui"},{"label":"Komplektacija","value":"Įrenginys, instrukcija"}]', '[{"question":"Ar tiks mano automobiliui?","answer":"Įrenginys skirtas daugumai automobilių su standartine OBD2 jungtimi. Prieš perkant rekomenduojame patikrinti savo automobilio modelio suderinamumą."},{"question":"Ar programėlė pridedama?","answer":"Įrenginys veikia su populiariomis suderinamomis diagnostikos programėlėmis. Trumpa prijungimo instrukcija yra komplekte."},{"question":"Per kiek laiko gausiu prekę?","answer":"Užsakymus Lietuvoje išsiunčiame per 1–2 darbo dienas."}]', 'OBD2 automobilio diagnostikos įrenginys'),
	(gen_random_uuid()::text, 'automobilio-laikiklis', 'active', 'automobiliui', 'Milishop', 'Apgalvoti daiktai kasdienai.', 'Magnetinis automobilio telefono laikiklis', 'Milishop #02 · Kelionei', 'Stabilus, minimalus ir pasiruošęs kiekvienai kelionei.', 'Laikiklis, kuris netrukdo. Tvirtas magnetas, patogus kampas ir minimalus dizainas padeda telefoną turėti ten, kur jo reikia — prieš akis, bet ne kelyje. Jis lengvai įsilieja į automobilio saloną ir neužima daugiau vietos nei būtina.', '24,90 €', '29,90 €', 'https://images.pexels.com/photos/12953565/pexels-photo-12953565.jpeg?auto=compress&cs=tinysrgb&w=1600', '["https://images.pexels.com/photos/12953565/pexels-photo-12953565.jpeg?auto=compress&cs=tinysrgb&w=1600","https://images.pexels.com/photos/86993/pexels-photo-86993.jpeg?auto=compress&cs=tinysrgb&w=1200"]', '["Stiprus magnetinis laikymas","Pasukamas žiūrėjimo kampas","Montuojamas be įrankių"]', '["Nuvalyk pasirinkto paviršiaus vietą","Pritvirtink laikiklio pagrindą","Uždėk magnetinį žiedą ir telefoną"]', '[{"label":"Tvirtinimas","value":"Magnetinis"},{"label":"Korpusas","value":"Aliuminis ir ABS"},{"label":"Reguliavimas","value":"360° kampas"},{"label":"Komplektacija","value":"Laikiklis, žiedas, lipni bazė"}]', '[{"question":"Ar laikiklis tiks storam telefono dėklui?","answer":"Dažniausiai taip, jei magnetinis žiedas pritvirtintas prie dėklo išorės. Labai stori ar metaliniai dėklai gali sumažinti laikymo jėgą."},{"question":"Ar galima keisti kampą?","answer":"Taip, laikiklio galvutė pasisuka 360°, todėl patogų kampą rasi tiek navigacijai, tiek skambučiams."},{"question":"Ar galima nuimti nepaliekant žymių?","answer":"Pagrindą nuimk lėtai, šildydamas lipnią dalį. Naudojant pagal instrukciją, paviršius lieka švarus."}]', 'Magnetinis automobilio telefono laikiklis'),
	(gen_random_uuid()::text, 'namu-akcentas', 'active', 'namams', 'Milishop', 'Apgalvoti daiktai kasdienai.', 'Keraminė stalo detalė „Forma“', 'Milishop #03 · Namams', 'Mažas akcentas, kuris suteikia erdvei daugiau jaukumo.', 'Rankų darbo įkvėpta keraminė detalė su natūralia tekstūra ir tyliu charakteriu. Tinka vienai, poroje ar kaip maža dovana žmogui, kuris vertina daiktų paprastumą. Kiekvienas paviršius turi subtilių skirtumų, todėl kiekviena detalė yra šiek tiek sava.', '32,00 €', '', 'https://images.pexels.com/photos/15028227/pexels-photo-15028227.jpeg?auto=compress&cs=tinysrgb&w=1600', '["https://images.pexels.com/photos/15028227/pexels-photo-15028227.jpeg?auto=compress&cs=tinysrgb&w=1600","https://images.pexels.com/photos/86993/pexels-photo-86993.jpeg?auto=compress&cs=tinysrgb&w=1200"]', '["Natūrali keramikos tekstūra","Tinka įvairiam interjerui","Gera dovanos idėja"]', '["Išsirink vietą, kur norisi mažo akcento","Sukomponuok su mėgstamais daiktais","Mėgaukis tyliu kasdieniu grožiu"]', '[{"label":"Medžiaga","value":"Keramika"},{"label":"Priežiūra","value":"Valyti sausa šluoste"},{"label":"Spalva","value":"Natūrali smėlio"},{"label":"Komplektacija","value":"1 keraminė detalė"}]', '[{"question":"Ar kiekviena detalė vienoda?","answer":"Ne visai. Natūrali tekstūra ir rankų darbo įkvėptas procesas reiškia, kad kiekvienas paviršius gali turėti mažų, gražių skirtumų."},{"question":"Kaip ją prižiūrėti?","answer":"Valykite minkšta sausa arba vos drėgna šluoste. Nenaudokite abrazyvių valiklių."},{"question":"Ar tinka dovanai?","answer":"Taip. Detalė siunčiama saugiai supakuota ir tinka kaip subtili dovana įkurtuvių ar gimtadienio proga."}]', 'Keraminė stalo detalė „Forma“'),
	(gen_random_uuid()::text, 'medinis-svyravimas', 'active', 'namams', 'Milishop', 'Apgalvoti daiktai kasdienai.', 'Medinis vaikų sūpynės – su virve', 'Milishop pasirinkimas · Namams', 'Namuose laimingas ir aktyvus laikas.', 'Namuose laimingas ir aktyvus laikas.', '€142,00', '€162,00', 'https://images.unsplash.com/photo-1517705008128-361805f42e86?auto=compress&fit=crop&w=900&q=80', '["https://images.unsplash.com/photo-1517705008128-361805f42e86?auto=compress&fit=crop&w=900&q=80"]', '[]', '[]', '[]', '[]', 'Medinis vaikų sūpynės – su virve'),
	(gen_random_uuid()::text, 'garso-modulis', 'active', 'kasdienai', 'Milishop', 'Apgalvoti daiktai kasdienai.', 'Garso elektronikos sistema „Tesla“', 'Milishop pasirinkimas · Kasdienai', 'Garsas, stiprumas ir paprastas dizainas.', 'Garsas, stiprumas ir paprastas dizainas.', '€68,00', '€72,00', 'https://images.unsplash.com/photo-1518444065439-e933c06ce9a9?auto=compress&fit=crop&w=900&q=80', '["https://images.unsplash.com/photo-1518444065439-e933c06ce9a9?auto=compress&fit=crop&w=900&q=80"]', '[]', '[]', '[]', '[]', 'Garso elektronikos sistema „Tesla“'),
	(gen_random_uuid()::text, 'daugiafunkcinis-kratytuvas', 'active', 'kasdienai', 'Milishop', 'Apgalvoti daiktai kasdienai.', 'VAYOX insect killer – elektrinis', 'Milishop pasirinkimas · Kasdienai', 'Efektyvi apsauga nuo vabzdžių.', 'Efektyvi apsauga nuo vabzdžių.', '€84,00', '€104,00', 'https://images.unsplash.com/photo-1555099962-4199c345e5dd?auto=compress&fit=crop&w=900&q=80', '["https://images.unsplash.com/photo-1555099962-4199c345e5dd?auto=compress&fit=crop&w=900&q=80"]', '[]', '[]', '[]', '[]', 'VAYOX insect killer – elektrinis'),
	(gen_random_uuid()::text, 'parfumas', 'active', 'kasdienai', 'Milishop', 'Apgalvoti daiktai kasdienai.', 'Perceive Gift Set – perfumed', 'Milishop pasirinkimas · Kasdienai', 'Gaivus ir subtilus kvapas kasdienai.', 'Gaivus ir subtilus kvapas kasdienai.', '€80,00', '€100,00', 'https://images.unsplash.com/photo-1528740561666-dc2479d461a6?auto=compress&fit=crop&w=900&q=80', '["https://images.unsplash.com/photo-1528740561666-dc2479d461a6?auto=compress&fit=crop&w=900&q=80"]', '[]', '[]', '[]', '[]', 'Perceive Gift Set – perfumed')
