DELETE FROM "product_landings" AS duplicate
USING "product_landings" AS keeper
WHERE duplicate."slug" = keeper."slug"
	AND (duplicate."updated_at" < keeper."updated_at"
		OR (duplicate."updated_at" = keeper."updated_at" AND duplicate."id" < keeper."id"));
